await page.goto('/ops/operations');

const pick = async (re) => {
  for (const role of ['region', 'list', 'group', 'table', 'complementary', 'article', 'feed']) {
    const loc = page.getByRole(role, { name: re }).first();
    if (await loc.count()) return loc;
  }
  return page.getByRole('heading', { name: re }).first();
};

const ops = await pick(/operations/i);
const timeline = await pick(/timeline/i);
await expect(ops).toBeVisible();
await expect(timeline).toBeVisible();

const a = await ops.boundingBox();
const b = await timeline.boundingBox();

// Laid out in a row: side by side, the timeline to the right of operations, not stacked below.
const sideBySide = b.x >= a.x + a.width - 2 && Math.abs(b.y - a.y) < Math.min(a.height, b.height);
if (!sideBySide) {
  throw new Error(`Operations and timeline are not in a row: ops=${JSON.stringify(a)} timeline=${JSON.stringify(b)}`);
}
